"""Shared, script-free realm account presentation."""
from starlette.responses import HTMLResponse

STYLE = '''
*{box-sizing:border-box}body{margin:0;background:#091c22;color:#edf4e8;font:16px/1.6 system-ui,sans-serif}a{color:#9de5bd;text-underline-offset:5px}a:hover{color:white}header{padding:24px 6vw;display:flex;justify-content:space-between;border-bottom:1px solid #ffffff15;letter-spacing:.12em;font-size:12px}header strong{font-size:16px;letter-spacing:.07em}main{max-width:1380px;margin:auto;padding:6vh 6vw;display:grid;grid-template-columns:1.25fr 1fr;gap:7vw;align-items:center;min-height:85vh}.eyebrow{color:#b8cf98;font-size:11px;letter-spacing:.23em;text-transform:uppercase}.story h1{font:clamp(40px,5vw,72px)/1.06 Georgia,serif;margin:22px 0;color:#f3edd9}.story p{color:#9dbab5;max-width:440px}.landscape{position:relative;height:255px;overflow:hidden;border-radius:50% 50% 20px 20px;background:radial-gradient(ellipse at 68% 20%,#b9d59544,transparent 40%),linear-gradient(#11333b,#315247);margin-top:36px}.moon{position:absolute;right:25%;top:30px;width:46px;height:46px;border-radius:50%;background:#ece8b6;box-shadow:0 0 65px #e3df9977}.ridge{position:absolute;width:120%;height:190px;left:-10%;bottom:-40px;background:#173f3d;clip-path:polygon(0 80%,15% 35%,30% 65%,49% 0,65% 53%,80% 18%,100% 85%)}.ridge.front{background:#102f2c;transform:translate(60px,55px)}.village{position:absolute;bottom:25px;left:30%;display:flex;gap:22px;align-items:flex-end}.house{position:relative;width:50px;height:42px;background:#826951;border-radius:2px;box-shadow:12px 12px 0 #0b252c55}.house:before{content:'';position:absolute;top:-25px;left:-8px;border-left:33px solid transparent;border-right:33px solid transparent;border-bottom:28px solid #a57d5c}.house:after{content:'';position:absolute;bottom:9px;left:18px;width:12px;height:15px;background:#ffda83;box-shadow:0 0 20px #ffcf8188;animation:glow 5s ease-in-out infinite}.house:nth-child(2){transform:scale(.75)}.firefly{position:absolute;width:3px;height:3px;background:#d0edb4;border-radius:50%;box-shadow:0 0 10px #d0edb4;animation:float 8s ease-in-out infinite}.firefly:nth-child(5){left:20%;top:65%}.firefly:nth-child(6){left:75%;top:60%;animation-delay:-3s}.firefly:nth-child(7){left:40%;top:35%;animation-delay:-5s}.caption{display:flex;gap:22px;font-size:11px;letter-spacing:.1em;color:#99b5a5;margin-top:20px}.card{background:linear-gradient(135deg,#183333,#10282d);border:1px solid #55706a66;border-radius:20px;padding:clamp(24px,3.5vw,48px);box-shadow:0 24px 80px #0003;animation:arrive .6s ease-out}.card h1{font:36px/1.15 Georgia,serif;margin:0 0 12px}.card p{color:#b1c6c0}.card label{display:block;font-size:13px;color:#c9d8cf;margin-top:16px}.card input{display:block;width:100%;padding:13px 15px;margin-top:7px;border:1px solid #55716a;border-radius:8px;background:#092127;color:#fff;font:inherit}.card input:focus{outline:2px solid #b7d991;outline-offset:2px}.card button,.google{display:block;width:100%;padding:13px 16px;border-radius:8px;font:600 14px system-ui;text-align:center;cursor:pointer;transition:transform .18s,background .18s}.card button{margin-top:22px;background:#c4dda3;color:#17352b;border:0}.card button:hover{background:#e2edca;transform:translateY(-2px)}.google{border:1px solid #698278;text-decoration:none;color:#edf4e8;background:#ffffff05;margin:24px 0}.google:hover{background:#ffffff10}.divider{text-align:center;font-size:11px;letter-spacing:.15em;color:#8fa9a0;margin:20px 0}details{border-top:1px solid #ffffff20;margin-top:24px;padding-top:18px}summary{cursor:pointer;color:#b9dbb0;font-size:14px}small{display:block;color:#94ada4;font-size:12px;margin-top:20px}.admin-link{font-size:12px;display:block;margin-top:24px;color:#9ab5ae}footer{padding:20px 6vw;color:#78958f;font-size:11px;letter-spacing:.12em}@keyframes float{50%{transform:translate(20px,-18px);opacity:.3}}@keyframes glow{50%{opacity:.65}}@keyframes arrive{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}@media(max-width:800px){main{grid-template-columns:1fr;padding:32px 6vw;gap:30px}.story h1{font-size:42px}.landscape{height:150px;margin-top:20px}.caption{display:none}.story p{margin-bottom:0}.card h1{font-size:30px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
'''


def realm_page(content, status=200):
    return HTMLResponse('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aitizen Realm · Your story begins</title><style>'''+STYLE+'''</style></head><body>
<header><strong>◇ AITIZEN REALM</strong><span>A WORLD WITH A LIFE OF ITS OWN</span></header>
<main><section class="story"><span class="eyebrow">Explore · Connect · Belong</span><h1>A living world.<br>A story of your own.</h1><p>From quiet villages to distant shores, every citizen has a life to live. Find your place in the realm.</p>
<div class="landscape" role="img" aria-label="A moonlit mountain village with glowing windows and drifting fireflies"><div class="moon"></div><div class="ridge"></div><div class="ridge front"></div><div class="village"><i class="house"></i><i class="house"></i><i class="house"></i></div><i class="firefly"></i><i class="firefly"></i><i class="firefly"></i></div><div class="caption"><span>ONE SHARED WORLD</span><span>INDIVIDUAL STORIES</span><span>NEW DISCOVERIES</span></div></section>
<section class="card" aria-label="Account access">'''+content+'''</section></main><footer>AITIZEN REALM / EVERY LIFE LEAVES A STORY</footer></body></html>''', status_code=status, headers={'Cache-Control':'no-store','Referrer-Policy':'no-referrer','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'"})


PLAYER_FORM = '''<span class="eyebrow">Your next chapter</span><h1>Welcome to the realm.</h1><p>Sign in to meet your citizen.</p><a class="google" href="/account/google">Continue with Google</a><div class="divider">OR SIGN IN WITH EMAIL</div>
<form method="post" action="/account/password"><input type="hidden" name="action" value="login"><label>Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button>Sign in →</button></form>
<details><summary>New here? Create your account</summary><form method="post" action="/account/password"><input type="hidden" name="action" value="signup"><label>Citizen name<input name="name" maxlength="80" autocomplete="nickname" required></label><label>Email address<input name="email" type="email" autocomplete="email" required></label><label>Create password<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><button>Create account →</button></form><small>Confirm your email before signing in.</small></details><a class="admin-link" href="/admin/login">Realm administrator access</a>'''

ADMIN_FORM = '''<span class="eyebrow">Realm stewardship</span><h1>Welcome back, keeper.</h1><p>Sign in to manage the shared world.</p><form method="post" action="/login"><label>Owner access key<input name="key" type="password" required autocomplete="current-password"></label><button>Enter administration →</button></form><a class="admin-link" href="/account">← Return to player sign-in</a>'''
